//! Bootstrap process VM and TLS state. Ownership moves into Process when clone lands.
use crate::{arch::x86_64::{paging::{PhysAccess,PageTableRoot,PRESENT,WRITABLE,USER,NX},phys::Identity},sync::SpinLock,vm::{Map,VmFlags}};
use core::sync::atomic::{AtomicU64,Ordering};
const PAGE:u64=4096;/* Slot 129 keeps the heap out of the firmware identity map. */const BRK_BASE:u64=0x0000_4080_0000_0000;
static BRK:AtomicU64=AtomicU64::new(BRK_BASE);static FS_BASE:AtomicU64=AtomicU64::new(0);static CLEAR_CHILD_TID:AtomicU64=AtomicU64::new(0);
static VM:SpinLock<Map>=SpinLock::new(Map::new());
fn up(v:u64)->Result<u64,i64>{v.checked_add(PAGE-1).map(|x|x&!(PAGE-1)).ok_or(crate::errno::ENOMEM)}
fn pte_flags(prot:u64)->Result<u64,i64>{if prot&!7!=0{return Err(crate::errno::EINVAL)}Ok(USER|if prot&2!=0{WRITABLE}else{0}|if prot&4==0{NX}else{0})}
fn vm_flags(prot:u64)->Result<VmFlags,i64>{let mut f=VmFlags::USER;let _=pte_flags(prot)?;if prot&1!=0{f.0|=VmFlags::READ.0}if prot&2!=0{f.0|=VmFlags::WRITE.0}if prot&4!=0{f.0|=VmFlags::EXEC.0}f.0|=VmFlags::ANON.0;Ok(f)}
fn map_zeroed(start:u64,len:u64,prot:u64)->Result<(),i64>{let root=PageTableRoot::current();let phys=Identity;let flags=pte_flags(prot)?;let end=start.checked_add(len).ok_or(crate::errno::ENOMEM)?;let mut va=start;while va<end{let pa=match crate::memory::alloc_frame(){Some(v)=>v,None=>{rollback(start,va);return Err(crate::errno::ENOMEM)}};unsafe{phys.table(pa).fill(0)}if let Err(e)=root.map_page(&phys,va,pa,flags){let _=crate::memory::free_frame(pa);rollback(start,va);return Err(e)}va+=PAGE;}Ok(())}
fn rollback(start:u64,end:u64){let root=PageTableRoot::current();let phys=Identity;let mut va=start;while va<end{if let Ok(pa)=root.unmap_page(&phys,va){let _=crate::memory::free_frame(pa);}va+=PAGE;}}
fn unmap_pages(start:u64,len:u64)->Result<(),i64>{let root=PageTableRoot::current();let phys=Identity;let end=start.checked_add(len).ok_or(crate::errno::EINVAL)?;let mut va=start;while va<end{let pa=root.unmap_page(&phys,va)?;crate::memory::free_frame(pa)?;va+=PAGE;}Ok(())}
pub fn brk(request:u64)->u64{let old=BRK.load(Ordering::Relaxed);if request==0{return old}if request<BRK_BASE||request>=crate::usercopy::USER_MAX as u64{return old}let old_page=match up(old){Ok(v)=>v,Err(_)=>return old};let new_page=match up(request){Ok(v)=>v,Err(_)=>return old};if new_page>old_page{let len=new_page-old_page;let mut vm=VM.lock();let flags=match vm_flags(3){Ok(v)=>v,Err(_)=>return old};if vm.insert(old_page as usize,len as usize,flags).is_err(){return old}drop(vm);if map_zeroed(old_page,len,3).is_err(){let _=VM.lock().remove(old_page as usize,len as usize);return old}}else if new_page<old_page{return old}BRK.store(request,Ordering::Relaxed);request}
pub fn fs_base()->u64{FS_BASE.load(Ordering::Relaxed)}
pub fn set_fs_base(v:u64)->bool{if v<crate::usercopy::USER_MAX as u64{FS_BASE.store(v,Ordering::Relaxed);crate::task::set_current_fs_base(v);true}else{false}}
pub fn set_clear_child_tid(v:u64){CLEAR_CHILD_TID.store(v,Ordering::Relaxed)}
pub fn mmap(addr:usize,len:usize,prot:u64,flags:u64,fd:i64,offset:u64)->Result<usize,i64>{const MAP_FIXED:u64=0x10;const MAP_ANON:u64=0x20;if len==0{return Err(crate::errno::EINVAL)}if flags&MAP_ANON==0||fd!=-1||offset!=0{return Err(crate::errno::ENODEV)}if flags&!(MAP_FIXED|MAP_ANON|0x02)!=0{return Err(crate::errno::EINVAL)}let vf=vm_flags(prot)?;let size=up(len as u64)? as usize;let start={let mut vm=VM.lock();if flags&MAP_FIXED!=0{if addr&4095!=0{return Err(crate::errno::EINVAL)}vm.insert(addr,size,vf)?;addr}else{vm.allocate(size,vf)?}};if let Err(e)=map_zeroed(start as u64,size as u64,prot){let _=VM.lock().remove(start,size);return Err(e)}Ok(start)}
pub fn munmap(addr:usize,len:usize)->Result<(),i64>{if addr&4095!=0||len==0{return Err(crate::errno::EINVAL)}let size=up(len as u64)? as usize;unmap_pages(addr as u64,size as u64)?;VM.lock().remove(addr,size)}
pub fn mprotect(addr:usize,len:usize,prot:u64)->Result<(),i64>{if addr&4095!=0||len==0{return Err(crate::errno::EINVAL)}let size=up(len as u64)? as usize;let f=vm_flags(prot)?;let root=PageTableRoot::current();let phys=Identity;let flags=pte_flags(prot)?;let mut va=addr as u64;let end=va+size as u64;while va<end{root.protect_page(&phys,va,flags)?;va+=PAGE}VM.lock().protect(addr,size,f)}
pub fn mapped_for_test(addr:u64,write:bool)->bool{PageTableRoot::current().query(&Identity,addr).map(|(_,f)|f&PRESENT!=0&&f&USER!=0&&(!write||f&WRITABLE!=0)).unwrap_or(false)}
pub fn reset_exec_state(){BRK.store(BRK_BASE,Ordering::Relaxed);FS_BASE.store(0,Ordering::Relaxed);CLEAR_CHILD_TID.store(0,Ordering::Relaxed);*VM.lock()=Map::new();crate::task::set_current_fs_base(0);}
